#include "postquantiquecoin/cli/NodeCLI.h"
#include <iostream>
namespace pqc { NodeCLI::NodeCLI(Blockchain& c):chain_(c){} int NodeCLI::Execute(const std::vector<std::string>& a){ std::string cmd=a.empty()?"status":a[0]; if(cmd=="start"||cmd=="status"){ std::cout<<"height="<<chain_.GetHeight()<<" tip="<<chain_.GetTipHash()<<" mempool="<<chain_.GetMempool().Size()<<'\n'; return 0; } if(cmd=="printchain"){ for(uint64_t h=0; h<=chain_.GetHeight(); ++h){ auto b=chain_.GetBlockByHeight(h); if(b) std::cout<<h<<' '<<b->GetHash()<<'\n'; } return 0; } if(cmd=="getblockheight"&&a.size()>1){ auto b=chain_.GetBlockByHeight(std::stoull(a[1])); if(!b) return 1; std::cout<<b->GetHash()<<'\n'; return 0; } if(cmd=="getblock"&&a.size()>1){ auto b=chain_.GetBlockByHash(a[1]); if(!b) return 1; std::cout<<"height="<<b->header.height<<" txs="<<b->transactions.size()<<'\n'; return 0; } if(cmd=="mempool"){ std::cout<<chain_.GetMempool().Size()<<" tx, fees="<<chain_.GetMempool().GetTotalFeesEstimate()<<'\n'; return 0; } if(cmd=="validatechain"){ auto r=chain_.ValidateChain(); std::cout<<(r.IsOk()?"valid":"invalid: "+r.Error())<<'\n'; return r.IsOk()?0:1; } if(cmd=="balance"&&a.size()>1){ std::cout<<chain_.GetBalance(a[1])<<" atoms\n"; return 0; } std::cout<<"commands: start status printchain getblockheight getblock mempool validatechain balance\n"; return 1; } }
